public class InnerConnectionGlueConnectionInputFactory(Action<Humidifier.DataZone.ConnectionTypes.GlueConnectionInput> factoryAction = null) : SubResourceFactory<Humidifier.DataZone.ConnectionTypes.GlueConnectionInput>
{

    internal InnerConnectionAuthenticationConfigurationInputFactory AuthenticationConfigurationFactory { get; set; }

    internal InnerConnectionPhysicalConnectionRequirementsFactory PhysicalConnectionRequirementsFactory { get; set; }

    protected override Humidifier.DataZone.ConnectionTypes.GlueConnectionInput Create()
    {
        var glueConnectionInputResult = CreateGlueConnectionInput();
        factoryAction?.Invoke(glueConnectionInputResult);

        return glueConnectionInputResult;
    }

    private Humidifier.DataZone.ConnectionTypes.GlueConnectionInput CreateGlueConnectionInput()
    {
        var glueConnectionInputResult = new Humidifier.DataZone.ConnectionTypes.GlueConnectionInput();

        return glueConnectionInputResult;
    }
    public override void CreateChildren(Humidifier.DataZone.ConnectionTypes.GlueConnectionInput result)
    {
        base.CreateChildren(result);

        result.AuthenticationConfiguration ??= AuthenticationConfigurationFactory?.Build();
        result.PhysicalConnectionRequirements ??= PhysicalConnectionRequirementsFactory?.Build();
    }

} // End Of Class

